import * as THREE from './three.module.js';
export function createAdventureEffects(scene){
 const group=new THREE.Group();scene.add(group);const N=200,positions=new Float32Array(N*3),geo=new THREE.BufferGeometry();for(let i=0;i<N;i++){positions[i*3]=(Math.sin(i*17.2)*.5+.5)*70-35;positions[i*3+1]=(i%40)*.5;positions[i*3+2]=Math.cos(i*7.8)*30}geo.setAttribute('position',new THREE.BufferAttribute(positions,3));const material=new THREE.PointsMaterial({color:0xc5edf4,size:.1,transparent:true,opacity:.65,depthWrite:false});const particles=new THREE.Points(geo,material);group.add(particles);group.visible=false;
 const beacons=new THREE.Group();scene.add(beacons);for(let i=0;i<3;i++){const p=new THREE.Mesh(new THREE.TorusGeometry(1+i*.24,.025,6,64),new THREE.MeshBasicMaterial({color:i===1?0x9df0e2:0xffdd93,transparent:true,opacity:.6}));p.rotation.x=Math.PI/2;p.position.y=.4+i*.16;beacons.add(p)}beacons.visible=false;
 let weather='clear',reduced=false,season='autumn';
 return {set(w,r,s){weather=w;reduced=r;season=s},update(t,dt,center,active){group.visible=active&&!reduced;beacons.visible=active;group.position.set(center.x,0,center.z);beacons.position.set(center.x,0,center.z+4);beacons.rotation.y=t*.08;if(!group.visible)return;material.color.set(weather==='snow'?0xf3fbff:weather==='rain'?0x9ccdea:({spring:0xffbdd5,summer:0x93eee4,autumn:0xffbd78,winter:0xe5e2ff}[season]));material.size=weather==='rain'?.075:weather==='snow'?.13:.08;material.opacity=weather==='mist'?.18:.6;for(let i=0;i<N;i++){positions[i*3+1]-=dt*(weather==='rain'?13:weather==='snow'?1.5:.55);if(positions[i*3+1]<.2)positions[i*3+1]=20;positions[i*3]+=Math.sin(t*.4+i)*dt*.25}geo.attributes.position.needsUpdate=true},dispose(){scene.remove(group,beacons);geo.dispose();material.dispose()}};
}
